/**
 * Subsetted TTF fonts for the dynamic OG card renderer, embedded as
 * base64 -- satori needs static TTF/OTF font buffers, not the variable WOFF2
 * files this repo self-hosts for the actual product UI (assets/fonts/), and
 * an OG card's entire glyph budget is "Book N min with {host}", the brand
 * lockup and a clock, so a subset is a few KB per face.
 *
 * MIK customization: the faces are the MIK Architecture design system's
 * Catamaran (titles, ARCHITECTURE) and Mulish (MIK, the clock), replacing
 * Punctual's IBM Plex Mono and Schibsted Grotesk.
 *
 * Regenerate from the checked-in variable WOFF2s with fontTools
 * (`pip install fonttools[woff]`), pinning each weight with the instancer
 * because satori does not read variable axes:
 *
 *   python3 -c "
 *   from fontTools.ttLib import TTFont
 *   from fontTools.varLib import instancer
 *   f = TTFont('assets/fonts/catamaran-latin-wght-normal.woff2'); f.flavor = None
 *   instancer.instantiateVariableFont(f, {'wght': 600}).save('/tmp/cat600.ttf')"
 *   python3 -m fontTools.subset /tmp/cat600.ttf --unicodes="U+0020-007E" \
 *     --layout-features='' --no-hinting --desubroutinize \
 *     --output-file=/tmp/cat600.subset.ttf
 *   base64 -i /tmp/cat600.subset.ttf
 *
 * Same recipe for Catamaran 400 and Mulish 700 and 500
 * (mulish-latin-wght-normal.woff2). The U+0020-007E range is deliberate, not
 * just small: it is exactly what `isRenderSafe` (render.ts) requires of
 * every string before these fonts are ever used, so a subset can never be
 * asked to render a glyph it does not have.
 */

/** Catamaran SemiBold, printable ASCII only -- the title lines and initials. */
const CATAMARAN_600_SUBSET_B64 =
  ''

/** Catamaran Regular, printable ASCII only -- ARCHITECTURE in the lockup. */
const CATAMARAN_400_SUBSET_B64 =
  ''

/** Mulish Bold, printable ASCII only -- MIK in the lockup. */
const MULISH_700_SUBSET_B64 =
  ''

/** Mulish Medium, printable ASCII only -- the clock. */
const MULISH_500_SUBSET_B64 =
  ''

function base64ToBytes(b64: string): Uint8Array {
  const binary = atob(b64)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i)
  return bytes
}

let catamaran600: Uint8Array | undefined
let catamaran400: Uint8Array | undefined
let mulish700: Uint8Array | undefined
let mulish500: Uint8Array | undefined

/** Decoded once per isolate, not once per request. */
export function catamaran600Subset(): Uint8Array {
  return (catamaran600 ??= base64ToBytes(CATAMARAN_600_SUBSET_B64))
}

export function catamaran400Subset(): Uint8Array {
  return (catamaran400 ??= base64ToBytes(CATAMARAN_400_SUBSET_B64))
}

export function mulish700Subset(): Uint8Array {
  return (mulish700 ??= base64ToBytes(MULISH_700_SUBSET_B64))
}

export function mulish500Subset(): Uint8Array {
  return (mulish500 ??= base64ToBytes(MULISH_500_SUBSET_B64))
}
